{
  "narratives": [
    {
      "item_code": "S4_EYE",
      "title_raw": "가. 눈에 들어갔을 때",
      "start": "p2:L22",
      "end": "p2:L23"
    },
    {
      "item_code": "S4_SKIN",
      "title_raw": "나. 피부에 접촉했을 때",
      "start": "p2:L24",
      "end": "p2:L26"
    },
    {
      "item_code": "S4_INHAL",
      "title_raw": "다. 흡입했을 때",
      "start": "p2:L27",
      "end": "p2:L29"
    },
    {
      "item_code": "S4_INGEST",
      "title_raw": "라. 먹었을 때",
      "start": "p2:L30",
      "end": "p2:L31"
    },
    {
      "item_code": "S4_DOCTOR",
      "title_raw": "바. 기타 의사의 주의사항",
      "start": "p2:L32",
      "end": "p2:L33"
    }
  ],
  "extras": [
    {
      "after_item": "S4_EYE",
      "title_raw": "가. 눈에 들어갔을 때",
      "reason": "코드없음",
      "statements": [
        {
          "value": "15분 이상 다량의 물로 씻어내시오."
        ,
          "line": "p2:L22"
        },
        {
          "value": "의사의 치료를 받으시오."
        ,
          "line": "p2:L23"
        }
      ]
    ,
      "suggested_code": "S4_EYE"
    ,
      "line": "p2:L22"
    },
    {
      "after_item": "S4_SKIN",
      "title_raw": "나. 피부에 접촉했을 때",
      "reason": "코드없음",
      "statements": [
        {
          "value": "동상, 동결 사태가 발생하면 많은 양의 미지근한 물(41-46℃)로 즉시 씻어내시오. 화학물질에 오염된 의류와 신발을 벗기고 제거하시오."
        ,
          "line": "p2:L24"
        },
        {
          "value": "피부에 의복이 얼어서 붙은 경우 녹인 후 제거하시오."
        ,
          "line": "p2:L25"
        },
        {
          "value": "의사의 치료를 받으시오."
        ,
          "line": "p2:L26"
        }
      ]
    ,
      "suggested_code": "S4_SKIN"
    ,
      "line": "p2:L24"
    },
    {
      "after_item": "S4_INHAL",
      "title_raw": "다. 흡입했을 때",
      "reason": "코드없음",
      "statements": [
        {
          "value": "부작용이 발생하면 오염되지 않은 지역으로 이동시키시오."
        ,
          "line": "p2:L27"
        },
        {
          "value": "호흡하지 않을 경우 인공호흡을 실시하시오."
        ,
          "line": "p2:L28"
        },
        {
          "value": "의사의 치료를 받으시오."
        ,
          "line": "p2:L29"
        }
      ]
    ,
      "suggested_code": "S4_INHAL"
    ,
      "line": "p2:L27"
    },
    {
      "after_item": "S4_INGEST",
      "title_raw": "라. 먹었을 때",
      "reason": "코드없음",
      "statements": [
        {
          "value": "의식이 없으면 머리를 옆으로 돌려 기도폐쇄를 예방하시오."
        ,
          "line": "p2:L30"
        },
        {
          "value": "많은 양의 화학물질을 섭취한 경우 의사의 진찰을 받으시오."
        ,
          "line": "p2:L31"
        }
      ]
    ,
      "suggested_code": "S4_INGEST"
    ,
      "line": "p2:L30"
    },
    {
      "after_item": "S4_DOCTOR",
      "title_raw": "바. 기타 의사의 주의사항",
      "reason": "코드없음",
      "statements": [
        {
          "value": "흡입의 경우 산소의 공급을 고려 하시오."
        ,
          "line": "p2:L33"
        }
      ]
    ,
      "suggested_code": "S4_DOCTOR"
    ,
      "line": "p2:L32"
    }
  ]
}

